import { Image, Pressable, Text, TextInput, View } from 'react-native'

export function Profile({ name, onSave }: { name: string; onSave: (name: string) => void }) {
  const [draft, setDraft] = useState(name)
  return (
    <View style={{ padding: 16, gap: 8 }}>
      <Image source={{ uri: 'https://example.com/me.png' }} style={{ width: 64, height: 64 }} />
      <TextInput value={draft} onChangeText={setDraft} accessibilityLabel="Name" />
      <Pressable onPress={() => onSave(draft)} style={({ pressed }) => ({ opacity: pressed ? 0.6 : 1 })}>
        <Text>Save</Text>
      </Pressable>
    </View>
  )
}
